{
  "findings": [
    {
      "check_id": "CKV_GCP_79",
      "title": "Ensure SQL database is using latest Major version",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database is using PostgreSQL version 13, which is not the latest major version. Using the latest version ensures access to the latest security patches and features."
    },
    {
      "check_id": "CKV_GCP_51",
      "title": "Ensure PostgreSQL database 'log_checkpoints' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_checkpoints' flag is not set, which means checkpoint activity is not logged. This can hinder troubleshooting and performance analysis."
    },
    {
      "check_id": "CKV_GCP_52",
      "title": "Ensure PostgreSQL database 'log_connections' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_connections' flag is explicitly set to 'off', which prevents logging of connection attempts. This can make it harder to detect unauthorized access attempts."
    },
    {
      "check_id": "CKV_GCP_53",
      "title": "Ensure PostgreSQL database 'log_disconnections' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_disconnections' flag is not set, which means disconnection events are not logged. This can hinder auditing and troubleshooting."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is not set, which means lock wait events are not logged. This can make it harder to diagnose performance issues."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.trading_database",
      "severity": "MEDIUM",
      "explanation": "SSL enforcement is not explicitly enabled, which could allow unencrypted connections to the database, exposing sensitive data in transit."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"trading_database\" {\n  name             = \"real-time-financial-trading-platform-database-trading\"\n  database_version = \"POSTGRES_15\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-n1-standard-2\"\n    ip_configuration {\n      ipv4_enabled    = false\n      private_network = google_compute_network.trading_platform_vpc.id\n      require_ssl     = true\n    }\n    database_flags {\n      name  = \"log_connections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_disconnections\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_checkpoints\"\n      value = \"on\"\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n  }\n  depends_on = [google_service_networking_connection.private_vpc_connection]\n}",
  "fix_summary": "Updated the database version to the latest major version (PostgreSQL 15). Enabled SSL enforcement for secure connections. Set 'log_connections', 'log_disconnections', 'log_checkpoints', and 'log_lock_waits' flags to 'on' to improve logging and troubleshooting capabilities."
}
